export { SupportAnalytics } from "./support-analytics";
export { createSupportAnalyticsDemoData, createSupportAnalyticsDemoRecords, supportAnalyticsDemoData, supportAnalyticsDemoChannels } from "./support-analytics-demo-data";
export type { SupportAnalyticsDemoOptions, SupportAnalyticsDemoRecord } from "./support-analytics-demo-data";
export { supportAnalyticsLabels, supportAnalyticsEnglishLabels } from "./support-analytics-labels";
export type { SupportAnalyticsProps, SupportAnalyticsSnapshot, SupportAnalyticsActions, SupportAnalyticsActionContext, SupportAnalyticsTicketContext, SupportAnalyticsLabels, SupportAnalyticsRange, SupportAnalyticsChannel, SupportAnalyticsView, SupportAnalyticsState, SupportAnalyticsQuery, SupportAnalyticsMetric, SupportAnalyticsBucket, SupportTicket } from "./support-analytics-types";

"use client";
import { useId } from "react";
import { Bar, BarChart, Line, LineChart, ReferenceLine, XAxis, YAxis, type LabelProps } from "recharts";
