  </div>;
}
export function MetricTrend({ metric }: {
    metric: SupportAnalyticsMetric;
}) {
    const points = metricTrendPoints(metric);
    if (!points.some((point) => point.value !== null))
        return <span className="text-label text-fg-subtle">—</span>;
    return <ChartContainer className="h-8 min-h-0 w-20" config={{ value: { color: chartColor(1) } }} aria-hidden="true">
    <LineChart data={points} accessibilityLayer={false} margin={{ top: 4, right: 3, bottom: 4, left: 3 }}>
      <XAxis hide dataKey="timestamp" type="number" domain={["dataMin", "dataMax"]}/>
      <YAxis hide domain={["dataMin", "dataMax"]}/>
      <Line dataKey="value" type="linear" stroke="var(--color-value)" strokeWidth={1.5} dot={false} connectNulls={false} isAnimationActive={false}/>
    </LineChart>
  </ChartContainer>;
}

import type { SupportAnalyticsBucket, SupportAnalyticsMetric, SupportAnalyticsSnapshot } from "./support-analytics-types";
export function validValue(value: unknown): value is number {
    return typeof value === "number" && Number.isFinite(value) && value >= 0;
}
export function validCount(value: unknown): value is number { return validValue(value) && Number.isSafeInteger(value); }
export function validMetricValue(value: unknown, unit: SupportAnalyticsMetric["unit"]): value is number {
    return validValue(value) && (unit !== "ratio" || value <= 1);
}
export function formatCount(value: unknown, locale: string) {
    return validCount(value) ? new Intl.NumberFormat(locale).format(value) : "—";
}
export function formatMetric(value: unknown, unit: SupportAnalyticsMetric["unit"], locale: string) {
    if (!validMetricValue(value, unit))
        return "—";
    if (unit === "ratio")
        return new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 1 }).format(value);
    const minutes = Math.round(value / 60000);
    const zh = locale.startsWith("zh");
    if (value < 60000)
        return `${new Intl.NumberFormat(locale, { maximumFractionDigits: 0 }).format(value / 1000)}${zh ? "秒" : "s"}`;
    if (minutes < 60)
        return `${minutes}${zh ? "分钟" : "m"}`;
    return `${Math.floor(minutes / 60)}${zh ? "小时" : "h"}${minutes % 60 ? ` ${minutes % 60}${zh ? "分钟" : "m"}` : ""}`;
}
export function metricTrendPoints(metric: SupportAnalyticsMetric) {
    return metric.trend.filter((point) => Number.isFinite(point.timestamp) && Number.isFinite(new Date(point.timestamp).getTime()))
        .map((point) => ({ ...point, value: validMetricValue(point.value, metric.unit) ? point.value : null }));
}
export function comparison(value: unknown, previous: unknown, method: SupportAnalyticsMetric["comparison"]) {
    if (!validValue(value) || !validValue(previous))
        return null;
    if (method === "percentage-points")
        return (value - previous) * 100;
    if (previous === 0)
        return value === 0 ? 0 : null;
    return (value - previous) / previous * 100;
}
export function comparisonText(delta: number | null, locale: string, suffix: string) {
    return delta === null ? "—" : `${delta > 0 ? "+" : ""}${new Intl.NumberFormat(locale, { maximumFractionDigits: 1 }).format(delta)}${suffix}`;
}
export function trendSummary(data: SupportAnalyticsSnapshot) {
    const { start, end, observedThrough, bucketMs } = data.window;
    const windowValid = [start, end, observedThrough].every((value) => Number.isFinite(value) && Number.isFinite(new Date(value).getTime())) && start < end && observedThrough >= start && observedThrough <= end && validValue(bucketMs) && bucketMs > 0;
    const bucketsValid = windowValid && data.buckets.every((point, index) => Number.isFinite(point.start) && Number.isFinite(point.end) && point.end - point.start === bucketMs && point.start >= start && point.end <= end && (index === 0 || point.start === data.buckets[index - 1].end));
    const points: SupportAnalyticsBucket[] = bucketsValid ? data.buckets.map((point) => ({ ...point, count: point.start < observedThrough && validCount(point.count) ? point.count : null })) : [];
    const complete = bucketsValid && observedThrough === end && points.length > 0 && points[0].start === start && points.at(-1)!.end === end && points.every((point) => validCount(point.count));
    const total = complete ? points.reduce((sum, point) => sum + point.count!, 0) : null;
    return { points, complete, total, average: total !== null && validCount(total) ? total / points.length : null };
}
export function formatDate(timestamp: number, locale: string, timeZone: string, weekday = false) {
    return Number.isFinite(new Date(timestamp).getTime()) ? new Intl.DateTimeFormat(locale, { timeZone, ...(weekday ? { weekday: "short" } : { month: "short", day: "numeric" }) }).format(timestamp) : "—";
}
export function formatUpdated(timestamp: number, locale: string, timeZone: string, now?: number) {
    if (!Number.isFinite(new Date(timestamp).getTime()))
        return "—";
    if (now === undefined || !Number.isFinite(now) || now < timestamp)
        return new Intl.DateTimeFormat(locale, { timeZone, month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(timestamp);
    const seconds = Math.floor((timestamp - now) / 1000);
    const unit = Math.abs(seconds) < 60 ? "second" : Math.abs(seconds) < 3600 ? "minute" : "hour";
    return new Intl.RelativeTimeFormat(locale, { numeric: "auto" }).format(unit === "second" ? seconds : Math.trunc(seconds / (unit === "minute" ? 60 : 3600)), unit);
}

import type { SupportAnalyticsChannel, SupportAnalyticsMetric, SupportAnalyticsQuery, SupportAnalyticsSnapshot, SupportAnalyticsView, SupportTicket } from "./support-analytics-types";
const day = 86400000;
const totals = {
    "this-week": [622, 396, 190, 110],
    "last-30-days": [2577, 1610, 751, 431],
    "last-12-weeks": [4251, 3112, 3380, 2768],
};
const openCounts = { "this-week": [72, 47, 24, 12], "last-30-days": [291, 191, 87, 49], "last-12-weeks": [580, 420, 451, 371] };
const channels = ["email", "live-chat", "in-app", "social"] as const;
const names = ["Greta Hoffmann", "Jonas Weber", "Mateusz Kowalski", "Dev Malhotra", "Lily Hayes", "Kai Chen", "Noah Williams", "Sofia Costa"];
export interface SupportAnalyticsDemoRecord extends SupportTicket {
    firstReplyMs: number;
    resolutionMs: number | null;
    firstContact: boolean;
    reopened: boolean;
}
export interface SupportAnalyticsDemoOptions {
    resolvedTicketIds?: readonly string[];
    revision?: number;
    empty?: boolean;
}
/** Fixed, synthetic records. Aggregates are recalculated from the full fixture, never its four-row preview. */
export function createSupportAnalyticsDemoRecords(query: SupportAnalyticsQuery, options: SupportAnalyticsDemoOptions = {}): SupportAnalyticsDemoRecord[] {
    if (options.empty)
        return [];
    const length = query.range === "this-week" ? 7 : query.range === "last-30-days" ? 30 : 12;
    const bucketMs = query.range === "last-12-weeks" ? day * 7 : day;
    // Complete weeks in Asia/Shanghai; the demo clock is fixed at the end of September 13.
    const end = Date.UTC(2026, 8, 13, 16);
    const start = end - length * bucketMs;
    const resolved = new Set(options.resolvedTicketIds);
    return channels.flatMap((channel, channelIndex) => {
        if (query.channel !== "all" && channel !== query.channel)
            return [];
        const total = totals[query.range][channelIndex];
        const open = openCounts[query.range][channelIndex];
        const weights = Array.from({ length }, (_, index) => query.range === "last-12-weeks" ? 0.85 + index * 0.025 : 1.35 - index / length * 0.65);
        const weightTotal = weights.reduce((sum, value) => sum + value, 0);
        const bucketCounts = weights.map((weight) => Math.floor(total * weight / weightTotal));
        const remainder = total - bucketCounts.reduce((sum, count) => sum + count, 0);
        for (let index = 0; index < remainder; index += 1)
            bucketCounts[index % length] += 1;
        const replyFactors = bucketCounts.map((_, index) => 1 + Math.sin(index * 1.8) * 0.16 - index / length * 0.08);
        const replyMeanFactor = bucketCounts.reduce((sum, count, index) => sum + count * replyFactors[index], 0) / total;
        let index = 0;
        return bucketCounts.flatMap((_, reverseIndex) => {
            const bucketIndex = length - 1 - reverseIndex;
            return Array.from({ length: bucketCounts[bucketIndex] }, (_, position) => {
                const i = index++;
                const id = `${query.range}:${channel}:${i}`;
                const newlyResolved = resolved.has(id);
                const status = i < open && !newlyResolved ? "open" : "resolved";
                const firstReplyMs = (channel === "live-chat" ? 5 : channel === "email" ? 60 : channel === "in-app" ? 35 : 50) * 60000 * replyFactors[bucketIndex] / replyMeanFactor;
                const resolutionMs = status === "resolved" ? (newlyResolved ? 45 : channel === "live-chat" ? 48 : 413) * 60000 : null;
                return { id, number: `#HD-${3370 + channelIndex * 20000 + i}`, customer: names[i % names.length], subject: ["Billing question", "Account access", "Workspace settings", "API connection"][i % 4], channel, status, priority: i % 11 === 1 ? "urgent" : i % 5 === 2 ? "low" : "normal",
                    createdAt: start + bucketIndex * bucketMs + (bucketMs * (1 - (position + 1) / (bucketCounts[bucketIndex] + 1))), canResolve: true,
                    firstReplyMs, resolutionMs, firstContact: newlyResolved || ((i - open) * 37) % (total - open) < Math.round((total - open) * 0.728), reopened: i >= open && ((i - open) * 43) % (total - open) < Math.round((total - open) * 0.063),
                } satisfies SupportAnalyticsDemoRecord;
            });
        });
    }).sort((a, b) => b.createdAt - a.createdAt || a.id.localeCompare(b.id));
}
export function createSupportAnalyticsDemoData(query: SupportAnalyticsQuery = { range: "this-week", channel: "all" }, options: SupportAnalyticsDemoOptions = {}): SupportAnalyticsSnapshot {
    const records = createSupportAnalyticsDemoRecords(query, options);
    const length = query.range === "this-week" ? 7 : query.range === "last-30-days" ? 30 : 12;
    const bucketMs = query.range === "last-12-weeks" ? day * 7 : day;
    const end = Date.UTC(2026, 8, 13, 16);
    const start = end - length * bucketMs;
    const buckets = Array.from({ length }, (_, index) => ({ start: start + index * bucketMs, end: start + (index + 1) * bucketMs, count: records.filter((record) => record.createdAt >= start + index * bucketMs && record.createdAt < start + (index + 1) * bucketMs).length }));
    const viewData = (view: SupportAnalyticsView) => {
        const selected = records.filter((record) => view === "all" || record.status === view);
        const definitions = (view === "open" ? ["first-reply", "waiting", "sla-breach"] : view === "resolved" ? ["first-reply", "resolution", "reopened"] : ["first-reply", "resolution", "first-contact"]) as SupportAnalyticsMetric["id"][];
        const metrics = definitions.map((id): SupportAnalyticsMetric => {
            const ratio = ["sla-breach", "reopened", "first-contact"].includes(id);
            const samples = selected.filter((record) => !["resolution", "reopened", "first-contact"].includes(id) || record.status === "resolved");
            const measurement = (record: SupportAnalyticsDemoRecord) => id === "first-reply" ? record.firstReplyMs : id === "waiting" ? end - record.createdAt : id === "resolution" ? record.resolutionMs! : id === "sla-breach" ? Number(end - record.createdAt > 8 * 3600000) : id === "first-contact" ? Number(record.firstContact) : Number(record.reopened);
            const average = (items: readonly SupportAnalyticsDemoRecord[]) => items.length ? items.reduce((sum, record) => sum + measurement(record), 0) / items.length : null;
            const value = average(samples);
            return { id, unit: ratio ? "ratio" : "milliseconds", sampleSize: samples.length, aggregation: ratio ? "ratio" : "mean", value,
                previousValue: value === null ? null : ratio ? Math.max(0, Math.min(1, value - (id === "first-contact" ? 0.034 : 0.007))) : value / (id === "resolution" ? 1.025 : 0.945),
                target: id === "first-reply" ? 45 * 60000 : id === "first-contact" ? 0.7 : ratio ? 0.08 : 8 * 3600000,
                improvementDirection: id === "first-contact" ? "higher" : "lower", comparison: ratio ? "percentage-points" : "relative",
                trend: buckets.map((bucket) => ({ timestamp: bucket.start, value: average(samples.filter((record) => record.createdAt >= bucket.start && record.createdAt < bucket.end)) })),
            };
        });
        return { metrics, recentTickets: selected.slice(0, 4) };
    };
    const views = { all: viewData("all"), open: viewData("open"), resolved: viewData("resolved") };
    const total = records.length;
    return { ...query, id: `demo:${query.range}:${query.channel}`, revision: String(options.revision ?? 0), scopeId: "support-demo", window: { start, end, observedThrough: end, bucketMs }, previousWindow: { start: start - length * bucketMs, end: start }, updatedAt: end,
        total, previousTotal: Math.round(total / (query.channel === "live-chat" ? 1.16 : query.range === "this-week" ? 1.078 : 1.12)),
        counts: { open: records.filter((record) => record.status === "open").length, resolved: records.filter((record) => record.status === "resolved").length }, buckets, views,
    };
}
export const supportAnalyticsDemoData = createSupportAnalyticsDemoData();
export const supportAnalyticsDemoChannels: readonly SupportAnalyticsChannel[] = ["all", ...channels];

"use client";
import { Badge } from "@ui/badge";
import { ChartDataTable } from "@ui/chart-primitives";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@ui/table";
import { comparison, comparisonText, formatCount, formatDate, formatMetric, validMetricValue } from "./support-analytics-data";
import { MetricTrend } from "./support-analytics-charts";
import type { SupportAnalyticsLabels, SupportAnalyticsMetric } from "./support-analytics-types";
export function SupportMetrics({ metrics, labels, locale, timeZone, rangeLabel }: {
    metrics: readonly SupportAnalyticsMetric[];
    labels: SupportAnalyticsLabels;
    locale: string;
    timeZone: string;
    rangeLabel: string;
}) {
    return <div className="min-w-0 space-y-2">
    <Table>
      <TableHeader><TableRow><TableHead>{rangeLabel}</TableHead><TableHead>{labels.trend}</TableHead><TableHead className="text-right">{labels.actual}</TableHead><TableHead className="text-right">{labels.previous}</TableHead></TableRow></TableHeader>
      <TableBody>{metrics.map((metric) => {
            const available = validMetricValue(metric.value, metric.unit);
            const target = validMetricValue(metric.target, metric.unit);
            const met = available && target && (metric.improvementDirection === "higher" ? metric.value! >= metric.target! : metric.value! <= metric.target!);
            const delta = available && validMetricValue(metric.previousValue, metric.unit) ? comparison(metric.value, metric.previousValue, metric.comparison) : null;
            const improved = delta !== null && (metric.improvementDirection === "higher" ? delta > 0 : delta < 0);
            return <TableRow key={metric.id}>
          <TableCell><p className="min-w-32 text-body text-fg-default">{labels[metric.id]}</p><p className="mt-1 text-label text-fg-subtle">{target && <><span className={met ? "text-fg-success" : available ? "text-fg-danger" : "text-fg-subtle"}>{available ? met ? labels.met : labels.missed : labels.unknown}</span> · {labels.target} {formatMetric(metric.target, metric.unit, locale)}</>}<span className="block">{formatCount(metric.sampleSize, locale)} {labels.samples}</span></p></TableCell>
          <TableCell><MetricTrend metric={metric}/></TableCell>
          <TableCell className="whitespace-nowrap text-right font-medium tabular-nums text-fg-default">{formatMetric(metric.value, metric.unit, locale)}</TableCell>
          <TableCell className="text-right"><Badge size="sm" status={delta === null || delta === 0 ? "neutral" : improved ? "success" : "danger"}>{comparisonText(delta, locale, metric.comparison === "relative" ? "%" : ` ${labels.points}`)}</Badge></TableCell>
        </TableRow>;
        })}</TableBody>
    </Table>
    <ChartDataTable caption={labels.trend} summary={labels.values} columns={[labels.date, labels.trend, labels.actual]} rows={metrics.flatMap((metric) => metric.trend.map((point, index) => ({ id: `${metric.id}-${index}`, label: formatDate(point.timestamp, locale, timeZone), values: [labels[metric.id], formatMetric(point.value, metric.unit, locale)] })))}/>
  </div>;
}

"use client";
import { useId, useLayoutEffect, useRef, useSyncExternalStore, type FocusEvent } from "react";
import { animate, motion, MotionConfig } from "framer-motion";
import { Badge } from "@ui/badge";
import { spring } from "@lib/springs";
import { formatCount, validCount } from "./support-analytics-data";
import type { SupportAnalyticsChannel, SupportAnalyticsLabels } from "./support-analytics-types";
const channels: SupportAnalyticsChannel[] = ["all", "email", "live-chat", "in-app", "social"];
const highlight = { base: "var(--brand)", onStrong: "var(--fg-on-brand)" };
const selectedText = { ...highlight, softBackground: "var(--muted)", onSoft: "var(--fg-on-brand)" };
const motionQuery = "(prefers-reduced-motion: reduce)";
function subscribeMotionPreference(onChange: () => void) {
    const media = window.matchMedia(motionQuery);
    media.addEventListener("change", onChange);
    return () => media.removeEventListener("change", onChange);
}
function getMotionPreference() { return window.matchMedia(motionQuery).matches; }
function getServerMotionPreference() { return true; }
function useReducedMotion() {
    return useSyncExternalStore(subscribeMotionPreference, getMotionPreference, getServerMotionPreference);
}
export function SupportTotal({ value, locale }: {
    value: number | null;
    locale: string;
}) {
    const element = useRef<HTMLSpanElement>(null);
    const displayed = useRef<number | null>(validCount(value) ? value : null);
    const reducedMotion = useReducedMotion();
    useLayoutEffect(() => {
        const target = element.current;
        if (!target)
            return;
        if (!validCount(value) || reducedMotion || displayed.current === null || displayed.current === value) {
            displayed.current = validCount(value) ? value : null;
            target.textContent = formatCount(value, locale);
            return;
        }
        // Retarget from the currently displayed value, including an interrupted transition.
        const formatter = new Intl.NumberFormat(locale);
        target.textContent = formatter.format(Math.round(displayed.current));
        const controls = animate(displayed.current, value, {
            ...spring.slow,
            duration: spring.slow.duration * 2,
            bounce: 0,
            onUpdate: (next) => {
                displayed.current = next;
                target.textContent = formatter.format(Math.round(next));
            },
            onComplete: () => {
                displayed.current = value;
                target.textContent = formatter.format(value);
            },
        });
        return () => controls.stop();
    }, [value, locale, reducedMotion]);
    return <span><span ref={element} aria-hidden="true">{formatCount(value, locale)}</span><span className="sr-only">{formatCount(value, locale)}</span></span>;
}
export function SupportChannelBadges({ channel, labels, onChange, onFocus }: {
    channel: SupportAnalyticsChannel;
    labels: SupportAnalyticsLabels;
    onChange: (channel: SupportAnalyticsChannel) => void;
    onFocus: (event: FocusEvent<HTMLDivElement>) => void;
}) {
    const indicatorId = useId();
    const reducedMotion = useReducedMotion();
    // Own the live preference below; the projection engine otherwise freezes its
    // reduced-motion setting when it first mounts during hydration.
    return <MotionConfig reducedMotion="never">
    <motion.div layoutScroll className="overflow-x-auto" onFocus={onFocus}>
      <div role="group" aria-label={labels.channels} className="relative isolate flex min-w-max items-center gap-2 p-1">
        {channels.map((item) => {
            const indicator = <Badge variant="strong" color={highlight} className="h-full w-full"><span className="invisible">{labels[item]}</span></Badge>;
            return <div key={item} className="relative shrink-0">
          {channel === item && (reducedMotion
                    ? <div aria-hidden="true" className="pointer-events-none absolute inset-0 z-10">{indicator}</div>
                    : <motion.div layoutId={indicatorId} initial={false} transition={spring.moderate} aria-hidden="true" className="pointer-events-none absolute inset-0 z-10">{indicator}</motion.div>)}
          <Badge color={channel === item ? selectedText : "gray"} role="button" tabIndex={0} aria-pressed={channel === item} className="cursor-pointer outline-none transition-colors duration-fast ease-out motion-reduce:transition-none focus-visible:ring-2 focus-visible:ring-focus-ring" onClick={() => onChange(item)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") {
                event.preventDefault();
                if (!event.repeat)
                    onChange(item);
            } }}>
            <span className="relative z-20">{labels[item]}</span>
          </Badge>
        </div>;
        })}
      </div>
    </motion.div>
  </MotionConfig>;
}

"use client";
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@ui/accordion";
import { Avatar, AvatarFallback, AvatarImage } from "@ui/avatar";
import { Badge } from "@ui/badge";
