function SupportAnalyticsContent({ scopeId, data, range, channel, onRangeChange, onChannelChange, view = "all", onViewChange, ticketsExpanded = false, onTicketsExpandedChange, state = "ready", refreshing = false, retainDataOnError = false, statusMessage, actions, labels: overrides, locale = "zh-CN", timeZone = "Asia/Shanghai", now, className, defaultView: _defaultView, defaultTicketsExpanded: _defaultTicketsExpanded, ...props }: SupportAnalyticsProps) {
