    </>}
    <ContainerFooter className="justify-between">
      <p className="min-w-0 text-label text-fg-subtle">{labels.updated} {usable ? formatUpdated(usable.updatedAt, locale, timeZone, now) : labels.unknown}</p>
      <div className="flex flex-wrap items-center gap-2">{actions?.onRefresh && context && <Tooltip content={labels.refresh}><Button iconOnly size="sm" variant="ghost" loading={refreshBusy} aria-label={labels.refresh} onClick={() => void run("refresh", () => actions.onRefresh!(context))}><Refresh aria-hidden/></Button></Tooltip>}{actions?.onOpenQueue && <Button size="sm" variant="secondary" disabled={!context} loading={pending.has("queue")} onClick={() => { if (context)
        void run("queue", () => actions.onOpenQueue!(context)); }}>{labels.queue}</Button>}</div>
    </ContainerFooter>
  </Container>;
}
